SELECT EXISTS (
    SELECT 1
      FROM chat_business_hour
     WHERE is_active = 1
       AND day_of_week = #{dayOfWeek}
       AND start_time <= #{time}
       AND end_time > #{time}
)

SELECT end_time
  FROM chat_business_hour
 WHERE is_active = 1
   AND day_of_week = #{dayOfWeek}
   AND start_time <= #{time}
   AND end_time > #{time}
 LIMIT 1

SELECT EXISTS (
    SELECT 1 FROM chat_holiday WHERE holiday_date = #{date}
)
